Here's how to handle each scenario with modern MSTest attributes:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PlatformAndEnvironmentTests
{
    private readonly TestContext _testContext;
    private string? _tempFilePath;

    public PlatformAndEnvironmentTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only (skipped on Linux/macOS)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\...", "Key", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (local-only, needs GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void GpuRendering_ProducesExpectedOutput()
    {
        var result = GpuRenderer.Render(scene);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await _weatherClient.GetForecastAsync(
            _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
    }

    // 4. Cleanup temp files even if test fails
    [TestMethod]
    public void Export_CreatesValidFile()
    {
        _tempFilePath = Path.GetTempFileName();
        Exporter.WriteTo(_tempFilePath);
        Assert.IsTrue(File.Exists(_tempFilePath));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFilePath is not null && File.Exists(_tempFilePath))
        {
            File.Delete(_tempFilePath);
        }
    }
}
```

**Key points:**

| Scenario | Solution | Min Version |
|---|---|---|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` | MSTest 3.10+ |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | MSTest 3.10+ |
| Flaky API | `[Retry(3)]` | MSTest 3.9+ |
| Cleanup on failure | `[TestCleanup]` method | All versions |

- **`[OSCondition]`** — cleanly skips the test on non-matching OSes (no `Assert.Inconclusive` hacks).
- **`[CICondition(ConditionMode.Exclude)]`** — detects CI via standard env vars (`CI`, `TF_BUILD`, `GITHUB_ACTIONS`, etc.) and skips accordingly.
- **`[Retry(3)]`** — use only for genuinely flaky external dependencies, not to mask race conditions.
- **`[TestCleanup]`** — runs after every test regardless of pass/fail, guaranteeing resource cleanup. For `IDisposable` resources, you can also implement `IDisposable`/`IAsyncDisposable` on the test class.
